class Solution {
    public int partitionString(String s){
        int groups=1,mask=0;
        for(char ch:s.toCharArray()){
            int bit=1<<(ch-'a');
            if((mask&bit)!=0){
                groups++;
                mask=0;
            }
            mask|=bit;
        }
        return groups;
    }
}

code.kotlin:
class Solution {
    fun partitionString(s:String):Int{
        var groups=1;
        var mask=0;
        for(ch in s){
            val bit=1 shl (ch-'a');
            if(mask and bit!=0){
                groups++;
                mask=0
            };
            mask=mask or bit
        };
        return groups
    }
}

